import{at as e,it as t,n,vt as r}from"./chunks/framework.fhiXEbOi.js";var i=JSON.parse(`{"title":"Attach a local test wallet","description":"Use the existing shared fixture wallet in an isolated browser tab for Pay-to-Play, Escrow or Bike NFT.","frontmatter":{"title":"Attach a local test wallet","description":"Use the existing shared fixture wallet in an isolated browser tab for Pay-to-Play, Escrow or Bike NFT.","outline":false},"headers":[],"relativePath":"start/fixture-wallet.md","filePath":"start/fixture-wallet.md"}`),a={name:`start/fixture-wallet.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="attach-a-local-test-wallet" tabindex="-1">Attach a local test wallet <a class="header-anchor" href="#attach-a-local-test-wallet" aria-label="Permalink to “Attach a local test wallet”">​</a></h1><div class="ported-guide"><p>Use the demo&#39;s public test accounts without installing a wallet extension. The attachment targets one existing demo tab; it starts no blockchain, app or browser.</p><dl><dt>Run on</dt><dd>The workstation running the local demo, from its source checkout.</dd><dt>Requires</dt><dd>A running GUI fixture on chain 31337, its complete printed URL and a separate Chrome/Chromium profile.</dd><dt>Changes</dt><dd>An injected wallet and role selector in that tab. Confirmed sends submit local test transactions immediately.</dd><dt>Success</dt><dd>The app connects to the selected fixture account and a permitted transaction reaches a successful receipt.</dd></dl><h2 id="browser">1. Open a dedicated browser</h2><p>Keep the app&#39;s GUI-launch terminal running. Start this browser in another terminal; use <code>chromium</code> instead when that is your installed executable:</p><pre><code>google-chrome \\
  --remote-debugging-address=127.0.0.1 \\
  --remote-debugging-port=9222 \\
  --user-data-dir=&quot;$HOME/.cache/cam-local-test-browser&quot; \\
  --no-first-run</code></pre><p>Open the <strong>entire URL printed by the demo</strong>, including its query parameters. Keep this profile exclusively for fixtures, with no real accounts or wallet extensions. The debugging endpoint controls that browser: keep it on loopback, never on a public interface.</p><h2 id="attach">2. Attach to the matching tab</h2><p>In another terminal, run from the same checkout. Replace the context, project and app with those used by your running demo:</p><pre><code>make viewer/local/fixture-wallet/attach \\
  DOCKER_CONTEXT=your-local-context COMPOSE_PROJECT_NAME=cam-demo \\
  FIXTURE_WALLET_APP=escrow \\
  CDP_ORIGIN=http://127.0.0.1:9222</code></pre><table><thead><tr><th>App value</th><th>Selector accounts</th><th>Initial account</th></tr></thead><tbody><tr><td><code>pay-to-play</code></td><td>admin, customer, relayer, recipient</td><td>customer</td></tr><tr><td><code>escrow</code></td><td>client, contractor, arbitrator</td><td>client</td></tr><tr><td><code>bike-nft</code></td><td>seller, mechanic, buyer</td><td>seller</td></tr></tbody></table><p>The launcher reads the existing demo&#39;s saved deployment volume and finds tabs matching its origin, host and local chain. One match is selected automatically; several matches prompt in the terminal. It checks the manifest, ABIs and original contract bindings and refuses a tab that already has a wallet. You do not need to copy a tab ID, manifest hash or contract address.</p><p>Keep the attachment terminal running. Its account labels are not permissions: the contracts decide what those addresses may do. Attachment does not fund accounts. In particular, arrange local test gas for Bike&#39;s mechanic and buyer before asking them to send.</p><h2 id="send">3. Connect, choose a role and confirm in the browser</h2><p>Select <strong>Connect wallet</strong> in the app. Change accounts through the fixture selector and wait for the app&#39;s updated view before preparing another action. The selector&#39;s <strong>Reconnect wallet</strong> control requests connection using its current account.</p><p>After reviewing a transaction, choose <strong>Send with wallet</strong>. A <strong>browser confirmation dialog</strong> asks whether to submit as the selected fixture account. Confirming signs and submits immediately; cancelling sends nothing. There is no terminal approval ceremony for this injected fixture wallet. It is distinct from the operator release-approval tool.</p><p>Wait for a successful receipt and refreshed app state. A submitted transaction cannot be undone by closing the wallet. Voucher signing remains a separate signer task. Private fixture keys stay in the test process, not in the page&#39;s role selector.</p><h2 id="refresh">After editing or reloading</h2><p>Reloading resets the selector to the app&#39;s configured initial account; reconnect in the app. After changing demo resources, use that app&#39;s <code>local/demo/gui/refresh</code> target with the same project and GUI settings. It preserves contracts and balances while rebuilding the viewer, checking CAM files and updating the fixture&#39;s manifest hash when needed. Reload and restart wallet attachment if its pinned manifest changed.</p><h2 id="stop">4. Detach, then stop the demo</h2><p>Ctrl-C in the attachment terminal removes the provider and selector and rejects pending requests without closing the tab. It prevents new signing/submission phases; it cannot reverse an already submitted transaction. After a forced kill, reload the tab before attaching again.</p><p>Stop the app&#39;s GUI launcher separately and let cleanup finish. Its matching <code>local/demo/gui/down</code> target removes the owned demo when necessary. Close the dedicated browser when finished; its profile remains on disk. Never use these public keys for real funds.</p><p><strong>No matching tab:</strong> check the complete printed URL and matching context/project. <strong>Existing provider:</strong> use the dedicated profile. <strong>Unavailable action:</strong> inspect the account, loaded object and current contract state. Do not weaken attachment checks to bypass a mismatch.</p><p>Implementation: <a href="https://github.com/numpde/dapp32/blob/04a18763700bbaa25cad73b9806d236ab4d5e139/js/tools/browser-fixture-wallet.mjs#L243-L254">browser confirmation and submission</a>, <a href="https://github.com/numpde/dapp32/blob/04a18763700bbaa25cad73b9806d236ab4d5e139/js/tools/browser-fixture-wallet-attach.mjs">attachment identity checks</a>. Continue with <a href="./local-wallet.html">Pay-to-Play&#39;s first deposit</a>, <a href="../use/escrow/">Escrow</a> or <a href="../use/bike-nft/">Bike NFT</a>.</p></div>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};